insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-crear-un-personaje-memorable$consejo$,
    1,
    $consejo$¿Cómo crear un personaje memorable?$consejo$,
    $consejo$Cómo crear un personaje memorable para tu historia: defectos, deseos, obstáculos y detalles que lo hacen real. Consejos de tía FriBuk.$consejo$,
    $consejo$Un buen personaje no tiene que ser perfecto, tiene que sentirse real. Dale una personalidad propia, deseos, miedos, manías y contradicciones. Piensa: ¿qué quiere conseguir y qué estaría dispuesto a hacer para lograrlo? Incluso un pequeño detalle puede hacer que un personaje se quede en la memoria.$consejo$,
    $consejo$sonrie$consejo$,
    $consejo$[{"heading": "", "text": "Un personaje perfecto es como una sopa sin sal: correcta, sana y absolutamente olvidable.\nLos personajes que nos acompañan años después de cerrar el libro no son perfectos. Son **reales**. Los recordamos como si los hubiéramos conocido: cómo hablaban, qué los hacía reír, qué decisión nos dejó con el corazón en la mano.\nLa buena noticia es que crear un personaje memorable no depende de ningún talento secreto. Depende de conocerlo bien. Vamos por partes."}, {"heading": "¿Por qué un personaje perfecto no funciona?", "text": "Porque nadie es así. Un personaje que siempre hace lo correcto, nunca duda y lo sabe todo puede ser admirable, pero rara vez es interesante. Lo que nos acerca a un personaje son sus **grietas**: sus miedos, sus manías, sus contradicciones.\nAlguien puede ser valiente para defender a un amigo y cobarde para decir «te quiero». Puede ser generoso con todo el mundo menos consigo mismo. Eso es una persona. Lo otro es un folleto.\nPregúntate en qué se equivoca tu personaje, qué parte de sí mismo esconde y qué haría que perdiera la calma. Ahí empieza lo bueno."}, {"heading": "¿Qué quiere tu personaje y qué se lo impide?", "text": "Todo personaje memorable **quiere algo**. Puede ser enorme, como salvar su mundo, o pequeño, como que su madre lo escuche por una vez. Lo importante es que lo quiera de verdad.\nJusto enfrente de ese deseo, pon un obstáculo: un miedo, otra persona, una regla, su propio orgullo. La historia nace en ese choque entre lo que el personaje quiere y lo que se lo impide.\nDespués piensa hasta dónde llegaría. ¿Mentiría? ¿Traicionaría a alguien? ¿Renunciaría a algo que ama? Las decisiones difíciles dicen más de un personaje que diez páginas de descripción.\nY te lo digo con cariño: si tu protagonista no quiere nada, el lector tampoco va a querer seguir leyendo."}, {"heading": "¿Qué detalles hacen inolvidable a un personaje?", "text": "A veces es un detalle: una frase que repite, un objeto que nunca suelta, la forma en que se ríe, cómo se toca el pelo cuando miente.\nEsos detalles funcionan como una firma. El lector los reconoce, los espera y, con el tiempo, los asocia con el personaje. No necesitas muchos: **uno o dos bien elegidos** valen más que diez adjetivos. No le cuelgues un llavero de rasgos."}, {"heading": "El tip de tía FriBuk: déjalo suelto", "text": "Crea a tu personaje y déjalo interactuar en tu imaginación o en tu escrito. Ponlo en una situación cualquiera (una fila del supermercado, una discusión, una mañana en que todo sale mal) y observa qué hace.\nVerás cómo, poco a poco, empieza a tomar decisiones que no tenías planeadas y su historia se va desarrollando sola. Es una de las partes más hermosas de escribir.\nSí, a veces te va a desobedecer. Es buena señal: significa que está vivo."}, {"heading": "Preguntas para conocer a tu personaje", "text": "Antes de escribir, responde estas preguntas. No todo tiene que aparecer en la historia: basta con que tú lo sepas.\n[•]¿Qué es lo que más desea en este momento?\n[•]¿Qué es lo que más le asusta?\n[•]¿Qué secreto no le ha contado a nadie?\n[•]¿Qué hace cuando está nervioso o enojado?\n[•]¿Qué diría de él su mejor amigo? ¿Y su peor enemigo?\nY no, «es misterioso» no es una personalidad."}, {"heading": "En resumen", "text": "Para crear un personaje memorable, dale defectos y contradicciones, un deseo claro y un obstáculo que se lo complique, uno o dos detalles que lo distingan, y déjalo actuar. Lo demás lo irás descubriendo mientras escribes."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$que-hacer-cuando-no-sabes-que-escribir$consejo$,
    2,
    $consejo$¿Qué hacer cuando no sabes qué escribir?$consejo$,
    $consejo$¿No sabes qué escribir? Ejercicios simples para encontrar ideas, destrabarte y volver a escribir tu historia. Consejos de tía FriBuk.$consejo$,
    $consejo$¡A todos nos ha pasado! A veces simplemente no aparece ninguna idea o no puedes desarrollar un escenario. Y está bien. Prueba escribir una escena absurda, inventar una conversación entre dos personajes o tomar una palabra y empezar desde ahí; también ayuda releer e imaginar distintos escenarios. No busques una gran historia desde el primer minuto: empieza escribiendo y deja que la idea aparezca. Y lo más importante: ¡diviértete!$consejo$,
    $consejo$pensativa$consejo$,
    $consejo$[{"heading": "", "text": "La página en blanco nos mira a todos con la misma cara de superioridad. Tienes ganas de escribir, abres el documento… y nada. Ni una idea. Ni un escenario. Ni siquiera un nombre decente para el protagonista.\nTranquilidad: no te pasa solo a ti, no significa que hayas perdido el talento y tiene arreglo. Aquí van mis recomendaciones para cuando no sabes qué escribir."}, {"heading": "¿Por qué a veces no se nos ocurre nada?", "text": "Casi siempre por exigencia. Nos sentamos esperando que aparezca la gran historia, la idea brillante, el primer párrafo perfecto. Y con tanta presión, la imaginación se esconde debajo de la cama.\nLas ideas no llegan mientras esperas sentado: llegan **mientras escribes**. La inspiración existe, pero tiene la mala costumbre de encontrarte trabajando."}, {"heading": "Baja la exigencia y empieza igual", "text": "No busques una gran historia desde el primer minuto. Escribe cualquier cosa: una frase, una imagen, un recuerdo. No tiene que servir, tiene que **destrabarte**.\nPiensa en el calentamiento antes de hacer deporte. Nadie corre una maratón sin estirar primero. Escribir funciona igual."}, {"heading": "Ejercicios para encontrar ideas", "text": "Cuando no sabes qué escribir, prueba alguno de estos:\n[#]**Una escena absurda.** Un dragón haciendo trámites en el banco. Un vampiro con alergia al ajo… y a todo lo demás. El absurdo suelta la mano.\n[#]**Una conversación entre dos personajes que se caen pésimo.** El conflicto genera ideas solo.\n[#]**Una palabra al azar.** Abre un libro en cualquier página, elige una palabra y empieza una historia desde ahí.\n[#]**Relee lo último que escribiste** e imagina tres caminos distintos para seguir. Elige el que más te sorprenda.\n[#]**Cambia el punto de vista.** Cuenta la misma escena desde los ojos del villano, del perro o de la vecina chismosa.\nNo tienen que quedar bien. Muchos terminan en la basura. Pero alguno, de vez en cuando, se convierte en una historia."}, {"heading": "¿Y si tengo la historia, pero no sé cómo seguirla?", "text": "Entonces el problema no es la idea, es el siguiente paso. Pregúntate qué quiere tu personaje en esta escena y qué podría salir mal. Casi siempre, la respuesta te muestra por dónde seguir.\nOtra opción: sáltate la escena difícil y escribe la que sí tienes clara. Nadie dijo que había que escribir en orden."}, {"heading": "Diviértete (en serio)", "text": "Escribir no es un trámite. Si tú no lo estás pasando bien, el lector lo va a notar. Juega, exagera, equivócate, escribe tonterías. Ya habrá tiempo de corregir.\nY si un día de verdad no sale nada, no pasa nada. Mañana es otro día y la página en blanco va a seguir ahí, igual de arrogante."}, {"heading": "Ideas para empezar una historia si estás en cero", "text": "Si de verdad no tienes nada, toma prestada una de estas premisas y hazla tuya. Nadie te va a acusar de nada: lo que importa es lo que hagas con ella.\n[•]Alguien recibe una carta escrita por sí mismo, con fecha de dentro de diez años.\n[•]Dos personas que se odian quedan atrapadas en un ascensor durante una noche entera.\n[•]Un pueblo donde nadie puede mentir, hasta que llega alguien que sí puede.\n[•]Una chica descubre que su mejor amiga no aparece en ninguna foto.\n[•]El villano de un cuento infantil decide contar su versión.\nElige la que te dé más curiosidad y hazte una sola pregunta: ¿qué pasaría después? Escribe la respuesta. Ya empezaste."}, {"heading": "En resumen", "text": "Cuando no sabes qué escribir, baja la exigencia, empieza con cualquier cosa y usa ejercicios como la escena absurda, la palabra al azar o el cambio de punto de vista. Las ideas aparecen escribiendo, no esperando."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-construir-una-historia-desde-cero$consejo$,
    3,
    $consejo$¿Cómo construir una historia desde cero?$consejo$,
    $consejo$Cómo construir una historia desde cero sin tenerlo todo resuelto: protagonista, deseo, conflicto y estructura básica. Consejos de tía FriBuk.$consejo$,
    $consejo$No necesitas tener toda la historia resuelta antes de empezar. Puedes partir con algo tan simple como: ¿quién es el protagonista, qué quiere y qué se lo impide? Desde ahí puedes ir construyendo el conflicto, los personajes y todo lo que ocurra después. Como tip personal de tía FriBuk, puedes imaginar el comienzo, el desarrollo y el desenlace como tema general, y luego ir creando las escenas y los detalles que harán tu historia única.$consejo$,
    $consejo$explica$consejo$,
    $consejo$[{"heading": "", "text": "Tienes una idea dando vueltas en la cabeza, pero cuando intentas escribirla no sabes por dónde agarrarla. Es normal: construir una historia desde cero da vértigo.\nTe cuento un secreto: no necesitas el mapa completo para salir de casa. Necesitas saber hacia dónde caminas. El resto se va armando por el camino."}, {"heading": "¿Necesito tener toda la historia resuelta antes de empezar?", "text": "No. Y si esperas a tenerla toda resuelta, probablemente nunca empieces. Muchas de las mejores ideas de una historia aparecen **mientras se escribe**, no antes.\nPlanificar cada detalle antes de escribir una sola línea es la forma más elegante de no escribir nunca."}, {"heading": "Las tres preguntas que sostienen cualquier historia", "text": "Toda historia, desde un cuento corto hasta una saga de cinco libros, se apoya en tres preguntas:\n[#]**¿Quién es tu protagonista?** No hace falta su biografía completa: basta con saber quién es y qué lo hace distinto.\n[#]**¿Qué quiere?** Un deseo claro, grande o pequeño, que lo empuje a actuar.\n[#]**¿Qué se lo impide?** El obstáculo: otra persona, una circunstancia, su propio miedo.\nSi puedes responder cada una en una línea, tienes una historia. Si no, tienes una idea bonita. Que también sirve, pero todavía no camina."}, {"heading": "¿Cómo pasar de la idea al conflicto?", "text": "El conflicto nace cuando el deseo choca con el obstáculo. Una chica quiere ganar un concurso de cocina, pero no sabe cocinar. Un chico quiere confesar lo que siente, pero su mejor amigo está enamorado de la misma persona.\nFíjate que en ambos casos ya hay preguntas: ¿lo logrará? ¿Qué está dispuesto a sacrificar? Esas preguntas son el motor de tu historia."}, {"heading": "El tip de tía FriBuk: comienzo, desarrollo y desenlace", "text": "Imagina esas tres partes a grandes rasgos, como un tema general:\n[•]**Comienzo:** ¿cómo es la vida del protagonista antes de que todo cambie?\n[•]**Desarrollo:** ¿qué se complica? ¿Qué intenta y qué le sale mal?\n[•]**Desenlace:** ¿cómo termina, más o menos? ¿Gana, pierde, cambia?\nCon eso basta para arrancar. No tiene que ser definitivo: el final que imaginas hoy puede cambiar mañana, y está bien."}, {"heading": "Las escenas y los detalles vienen después", "text": "Sobre esa base vas creando las escenas, los diálogos y los detalles que harán tu historia **única**. Ahí es donde aparece tu voz, tu humor, tu forma de ver el mundo.\nNo intentes resolverlo todo antes. Escribe una escena, después otra, y deja que la historia te vaya mostrando lo que necesita."}, {"heading": "Un ejemplo: de una idea a una historia", "text": "Veamos cómo funciona con una idea suelta: «una chica que puede escuchar los pensamientos de los demás».\n[#]**Protagonista:** Lucía, diecisiete años, tímida, cansada de saber lo que todos piensan de ella.\n[#]**Deseo:** quiere, por una vez, no saber. Tener una conversación normal.\n[#]**Obstáculo:** el único chico cuya mente no puede leer es justo el que guarda un secreto peligroso.\n[#]**Comienzo, desarrollo y desenlace:** lo conoce y se siente aliviada; descubre el secreto y todo se complica; tiene que elegir entre protegerlo o protegerse.\n¿Ves? En cinco minutos, la idea dejó de ser una frase bonita y se convirtió en una historia que se puede empezar a escribir hoy."}, {"heading": "En resumen", "text": "Para construir una historia desde cero, define quién es tu protagonista, qué quiere y qué se lo impide. Imagina el comienzo, el desarrollo y el desenlace a grandes rasgos, y deja que las escenas y los detalles aparezcan mientras escribes."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-organizar-una-trama$consejo$,
    4,
    $consejo$¿Cómo organizar una trama?$consejo$,
    $consejo$Cómo organizar la trama de tu historia o novela con un método simple: ordena los acontecimientos y haz que cada escena cuente. Consejos de tía FriBuk.$consejo$,
    $consejo$Cuando tienes muchas ideas, es fácil perderse. Anota los acontecimientos principales y ordénalos como si estuvieras armando un camino. ¿Qué ocurre primero? ¿Qué cambia después? ¿Y hacia dónde quieres llevar la historia? No necesitas tener cada detalle planeado.$consejo$,
    $consejo$completa$consejo$,
    $consejo$[{"heading": "", "text": "Tener muchas ideas es una bendición. Tenerlas todas al mismo tiempo, en desorden, es un cajón de cables: todo sirve, pero nada sale sin enredarse.\nSi sientes que tu historia se te escapa de las manos, que no sabes qué pasa primero ni hacia dónde va, lo que necesitas es organizar la trama. Tranquilidad: no hace falta una pizarra con hilos rojos como en las películas de detectives."}, {"heading": "¿Qué es la trama, en palabras simples?", "text": "La trama es **lo que pasa y en qué orden**. No es la idea general («una chica descubre que tiene poderes»), sino la cadena de acontecimientos: qué ocurre, qué provoca, qué cambia.\nUna buena trama hace que cada cosa lleve a la siguiente. Una trama desordenada parece una lista de cosas que le pasan al protagonista sin ninguna razón."}, {"heading": "Un método simple para organizar tu trama", "text": "Toma una hoja, un documento o el reverso de una boleta, y haz esto:\n[#]**Escribe el final que imaginas**, aunque después cambie. Saber hacia dónde vas ordena todo lo demás.\n[#]**Escribe el punto de partida**: cómo está tu protagonista al principio.\n[#]**Anota entre tres y cinco acontecimientos** que tienen que pasar entre medio para llegar de un punto al otro.\n[#]**Ordénalos** preguntándote: ¿qué ocurre primero? ¿Qué cambia después? ¿Qué provoca qué?\nListo. Eso es tu esqueleto. No es bonito, pero sostiene la historia."}, {"heading": "¿Cómo sé si una escena sobra?", "text": "Hazte esta pregunta: si quito esta escena, ¿la historia sigue exactamente igual? Si la respuesta es sí, esa escena sobraba. Duele, lo sé. Bórrala igual.\nUna escena sirve cuando **cambia algo**: lo que el personaje sabe, lo que quiere, lo que siente o lo que está en juego. Si nada cambia, es un paseo. Y el lector no vino a pasear."}, {"heading": "¿Y las subtramas?", "text": "Las historias secundarias (el romance del mejor amigo, el misterio del vecino) enriquecen la trama, pero también pueden enredarla. Haz la misma lista para cada una, más corta, y fíjate en qué momentos se cruzan con la historia principal.\nSi una subtrama nunca toca la historia principal, pregúntate si de verdad la necesitas."}, {"heading": "Deja espacio para sorprenderte", "text": "No necesitas tener cada detalle planeado. Un buen esquema es una guía, no una cárcel.\nSi a mitad de camino la historia quiere ir por otro lado, escúchala: a veces tiene mejores ideas que tú. Solo vuelve a tu lista y ajústala, para no perderte otra vez."}, {"heading": "¿Planificar todo o improvisar?", "text": "Hay quienes escriben con todo planificado, escena por escena, y quienes descubren la historia a medida que la escriben. Ninguna forma es mejor: son formas distintas de trabajar.\nSi planificar todo te aburre, haz solo la lista de acontecimientos principales y deja el resto a la improvisación. Si improvisar te hace perder el rumbo, detalla un poco más tu esquema antes de cada capítulo.\nLo importante es que tú sepas hacia dónde vas, aunque el camino tenga desvíos. Prueba, equivócate y quédate con lo que te funcione. Esa es tu manera de escribir."}, {"heading": "Herramientas simples para organizar tu trama", "text": "No necesitas programas especiales. Funcionan muy bien:\n[•]**Notas adhesivas o tarjetas:** una por acontecimiento. Las mueves hasta que el orden te convenza.\n[•]**Una tabla capítulo por capítulo:** qué pasa, qué cambia y con qué pregunta termina.\n[•]**Un documento con viñetas:** lo más simple, y a veces lo más útil.\nUsa la que te dé menos pereza. La mejor herramienta es la que de verdad vas a abrir."}, {"heading": "En resumen", "text": "Para organizar una trama, define el final y el punto de partida, anota los acontecimientos principales entre ambos y ordénalos según qué provoca qué. Elimina las escenas que no cambian nada y deja que el esquema te guíe sin encerrarte."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-escribir-dialogos-naturales$consejo$,
    5,
    $consejo$¿Cómo escribir diálogos naturales?$consejo$,
    $consejo$Cómo escribir diálogos naturales en tu historia: léelos en voz alta, usa el subtexto y dale a cada personaje su propia voz. Consejos de tía FriBuk.$consejo$,
    $consejo$Lee tus diálogos en voz alta. Si suenan como personas leyendo un guion, probablemente necesitan un poco más de naturalidad. Las personas no siempre dicen exactamente lo que piensan: se interrumpen, cambian de tema, evitan responder, mienten. Deja que tus personajes hablen como ellos, no como el escritor. Tip de tía FriBuk: ten cuidado con las onomatopeyas y las caritas hechas con el teclado; pueden resultar graciosas si buscas humor o naturalidad, pero no abuses de ellas.$consejo$,
    $consejo$senala$consejo$,
    $consejo$[{"heading": "", "text": "Si tus personajes hablan como un comunicado oficial, tenemos un problema. Ese diálogo… por favor.\nLos diálogos son de lo primero que el lector nota. Cuando suenan naturales, la historia fluye y los personajes cobran vida. Cuando suenan falsos, el lector siente que está leyendo un guion escolar. Veamos cómo escribir diálogos naturales."}, {"heading": "¿Cómo saber si un diálogo suena natural?", "text": "Léelo en voz alta. Es la prueba más simple y la más honesta. Si suena como personas leyendo un guion, si nadie hablaría así en la vida real, le falta naturalidad.\nY si te da vergüenza leerlo en voz alta, imagina lo que siente el lector."}, {"heading": "La gente no dice lo que piensa", "text": "En la vida real, las personas se interrumpen, cambian de tema, evitan responder, mienten y dicen una cosa queriendo decir otra. Mira:\n—¿Estás enojada?\n—No.\n—¿Segura?\n—Ya te dije que no.\nNadie dijo «sí», y todos lo entendimos. A eso se le llama **subtexto**: lo que no se dice también es diálogo. Un buen diálogo deja que el lector lea entre líneas."}, {"heading": "Que hable el personaje, no tú", "text": "Cada personaje tiene su forma de hablar. Uno es cortante, otro no para de dar vueltas, otro dice groserías cuando está nervioso, otro usa palabras complicadas para parecer inteligente.\nSi todos tus personajes suenan igual, suenan a ti. Prueba esto: tapa los nombres en un diálogo y fíjate si igual sabes quién está hablando."}, {"heading": "Errores comunes en los diálogos", "text": "[•]**Explicar lo que los personajes ya saben.** «Como sabes, hermano, nuestro padre murió hace diez años». Él lo sabe. Se lo estás contando al lector, y se nota.\n[•]**Saludos y despedidas eternas.** «Hola», «Hola, ¿cómo estás?», «Bien, ¿y tú?»… Corta y ve al grano.\n[•]**Demasiadas acotaciones.** No hace falta que cada línea diga «dijo enfadado» o «exclamó sorprendida». Si el diálogo está bien escrito, la emoción se entiende sola."}, {"heading": "El tip de tía FriBuk: con las onomatopeyas, calma", "text": "Cuidado con las onomatopeyas y las caritas hechas con el teclado. Pueden resultar graciosas si buscas humor o naturalidad, pero un capítulo lleno de «jajaja», «xD» y «:v» cansa rápido.\nÚsalas como la sal: poquito, y solo donde le aportan algo a la escena."}, {"heading": "¿Cómo se puntúan los diálogos en español?", "text": "En español, los diálogos se escriben con **raya** (—), no con comillas ni con guion corto (-). Las reglas básicas:\n[•]La raya va pegada a lo que dice el personaje: —Ven aquí.\n[•]Si después viene lo que hace o cómo lo dice, se abre otra raya: —Ven aquí —dijo su madre.\n[•]Si el personaje sigue hablando, se cierra la acotación con otra raya: —Ven aquí —dijo su madre—. Tenemos que hablar.\n[•]Si la acotación usa un verbo de habla (dijo, preguntó, susurró), empieza con minúscula. Si no lo usa, la frase del diálogo termina con punto: —Ya voy. —Se levantó del sillón.\nPuede parecer un detalle, pero un diálogo bien puntuado se lee mucho más fácil. Y quien lee lo agradece, aunque no sepa por qué."}, {"heading": "¿Cuánto diálogo debe tener un capítulo?", "text": "No hay una cantidad correcta. Depende de la escena: una discusión pide mucho diálogo; una persecución, casi nada.\nLo que sí conviene es el equilibrio. Páginas y páginas solo de diálogo cansan porque el lector pierde de vista dónde están y qué hacen los personajes. Páginas sin un solo diálogo pueden sentirse lentas. Alterna: diálogo, acción, un pensamiento, otra vez diálogo."}, {"heading": "En resumen", "text": "Para escribir diálogos naturales, léelos en voz alta, deja que los personajes no digan todo lo que piensan, dale a cada uno su propia voz y evita las explicaciones forzadas. Y con las onomatopeyas, moderación."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-describir-personajes-sin-aburrir$consejo$,
    6,
    $consejo$¿Cómo describir personajes sin aburrir?$consejo$,
    $consejo$Cómo describir a tus personajes sin aburrir al lector: elige pocos detalles, crea un rasgo distintivo y descríbelos en acción. Consejos de tía FriBuk.$consejo$,
    $consejo$No necesitas describir a un personaje de pies a cabeza para que el lector lo imagine. Elige algunos detalles que realmente aporten: una forma de mirar, una cicatriz, la ropa que siempre usa o incluso la manera en que camina. A veces un pequeño detalle dice mucho más que un párrafo entero, ¡e incluso podría ser el distintivo de tu personaje! Dime qué piensas si te digo: ¿joven mago con una cicatriz en la frente? ¡De eso se trata!$consejo$,
    $consejo$brazos-cruzados$consejo$,
    $consejo$[{"heading": "", "text": "Nadie necesita la ficha médica de tu protagonista. Altura, peso, color de ojos, de pelo, de uñas, número de zapato… para cuando terminas, el lector ya se durmió.\nDescribir personajes es necesario: el lector quiere imaginarlos. El problema es cómo lo hacemos. Te cuento cómo describir a tus personajes sin aburrir."}, {"heading": "¿Por qué las descripciones largas aburren?", "text": "Porque detienen la historia. Mientras enumeras rasgos, no pasa nada: nadie habla, nadie decide, nadie corre peligro. Y el lector, que vino por la historia, empieza a saltarse párrafos.\nAdemás, el lector **no necesita todo**. Con dos o tres pistas, su imaginación completa el resto. Y casi siempre lo hace mejor de lo que crees."}, {"heading": "Elige pocos detalles que digan mucho", "text": "En vez de describir todo, elige los detalles que realmente aporten algo:\n[•]Una forma de mirar: desafiante, cansada, siempre al suelo.\n[•]Una marca: una cicatriz, un tatuaje, un diente torcido.\n[•]La ropa que siempre usa, y lo que dice de él.\n[•]La manera en que camina, se sienta o se ríe.\nFíjate que cada uno de esos detalles cuenta algo de la personalidad, no solo del físico. Ese es el truco."}, {"heading": "¿Cómo crear un rasgo distintivo?", "text": "Te pregunto: ¿joven mago con una cicatriz en la frente? Exacto. No hizo falta decir nada más.\nUn buen detalle puede convertirse en el **distintivo** de tu personaje: lo que el lector recuerda y reconoce al instante. Búscalo. Puede ser físico, como unos lentes rojos, o un gesto, como una regla que nunca suelta. Sí, hablo por experiencia."}, {"heading": "Describe en movimiento", "text": "En vez de escribir «era nerviosa», muéstrala mordiéndose las uñas mientras espera una respuesta. En vez de «era muy alto», haz que tenga que agacharse al pasar por una puerta.\nDescribir a través de la acción tiene una ventaja enorme: la historia no se detiene. El lector conoce al personaje mientras lo ve hacer cosas."}, {"heading": "Reparte la descripción", "text": "No tienes que presentar a un personaje entero en su primera aparición. Da un par de detalles al principio y suelta los demás a lo largo de las escenas, cuando tengan sentido.\nSi en el capítulo cinco alguien le toma la mano, ese es un buen momento para mencionar sus manos ásperas. No en el capítulo uno, en medio de una lista."}, {"heading": "Un ejemplo: antes y después", "text": "**Antes:** «Martín era alto, de pelo castaño, ojos verdes, tenía veinte años, usaba siempre una chaqueta negra y era muy desconfiado».\n**Después:** «Martín entró sin quitarse la chaqueta negra, como si pensara irse en cualquier momento. Se sentó de espaldas a la pared, desde donde podía ver la puerta».\nEn la segunda versión no dijimos que era desconfiado: lo vimos. Y la chaqueta dejó de ser un dato para convertirse en parte de su personalidad.\nLa próxima vez que escribas una descripción, pregúntate si podrías mostrar ese rasgo con una acción. Casi siempre se puede, y casi siempre queda mejor."}, {"heading": "¿Y los personajes secundarios?", "text": "Con los secundarios, todavía menos. Un solo rasgo bien elegido basta para que el lector los distinga: la vecina que siempre huele a canela, el profesor que nunca termina sus frases.\nSi un personaje aparece una vez y no vuelve, no necesita descripción. Si va a ser importante, dale su rasgo distintivo desde la primera vez que aparezca, para que el lector lo reconozca cuando regrese."}, {"heading": "En resumen", "text": "Para describir personajes sin aburrir, elige pocos detalles que revelen su personalidad, busca un rasgo distintivo, descríbelos en acción y reparte la descripción a lo largo de la historia. Menos inventario, más personaje."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-empezar-el-primer-capitulo$consejo$,
    7,
    $consejo$¿Cómo empezar el primer capítulo?$consejo$,
    $consejo$Cómo empezar el primer capítulo de tu historia o novela para atrapar al lector: dónde comenzar, qué evitar y cómo terminarlo. Consejos de tía FriBuk.$consejo$,
    $consejo$El primer capítulo no tiene que explicar absolutamente todo. Puedes comenzar con una situación que despierte curiosidad: algo acaba de ocurrir, alguien recibe una noticia, aparece un problema o el protagonista está a punto de tomar una decisión. Haz que el lector quiera saber qué pasa después.$consejo$,
    $consejo$retrato$consejo$,
    $consejo$[{"heading": "", "text": "El primer capítulo es la puerta de entrada a tu historia. Si la puerta está trabada, nadie entra, por más bonita que sea la casa.\nPor eso da tanto miedo escribirlo. Pero no es una presentación con diapositivas: no tienes que explicar el mundo, la familia, el pasado y el clima. Tienes que lograr una sola cosa: **que el lector quiera leer el segundo**."}, {"heading": "¿Qué debe tener un buen primer capítulo?", "text": "Un buen comienzo presenta a alguien que nos interesa, en una situación que nos genera una pregunta. Eso es todo.\nNo hace falta que el lector entienda todo. Hace falta que tenga **curiosidad**. La explicación puede esperar; la curiosidad, no."}, {"heading": "¿Dónde empezar la historia?", "text": "Empieza donde algo se mueve. Algunas formas que funcionan:\n[•]**Algo acaba de ocurrir.** Una puerta rota, un mensaje sin responder, alguien que no volvió a casa.\n[•]**Alguien recibe una noticia.** Buena o mala, pero que lo cambie todo.\n[•]**Aparece un problema.** Pequeño o grande, pero que exija hacer algo.\n[•]**El protagonista está a punto de tomar una decisión.** El lector quiere ver qué elige.\nUn buen ejercicio: escribe tu primer capítulo y después prueba a borrar las primeras páginas. Muchas veces la historia empieza de verdad más adelante."}, {"heading": "¿Cuánto hay que explicar al principio?", "text": "Menos de lo que crees. El error más común es frenar la historia para contar la vida entera del protagonista, la historia del reino o cómo funciona la magia.\nConfía en el lector: puede entrar a una historia sin saberlo todo. De hecho, le gusta. Ve soltando la información de a poco, cuando la necesite."}, {"heading": "Lo que ya leímos demasiado", "text": "Te lo pido con cariño: que tu protagonista no se despierte, apague la alarma, se mire al espejo y se describa de pies a cabeza. Lo hemos leído. Muchas veces.\nTampoco hace falta empezar con el clima, salvo que el clima vaya a matar a alguien. Sorpréndenos."}, {"heading": "¿Cómo terminar el primer capítulo?", "text": "No hace falta un final explosivo. Basta con que el lector cierre el capítulo pensando «¿y ahora qué?». Una pregunta abierta, una decisión pendiente, una revelación pequeña.\nEse es tu objetivo: que la siguiente página sea irresistible."}, {"heading": "Ejemplos de primeras líneas que enganchan", "text": "Una buena primera línea no tiene que ser brillante: tiene que generar una pregunta. Fíjate en estas:\n[•]«El día que mi hermano desapareció, nadie en casa se dio cuenta hasta la cena».\n[•]«Tenía tres horas para devolver el anillo antes de que mi abuela notara que no estaba».\n[•]«Nunca había visto un fantasma, hasta que uno se sentó a mi lado en el bus».\nNinguna explica nada, y aun así queremos saber más. ¿Qué pasó con el hermano? ¿Por qué tiene el anillo? ¿Qué quiere el fantasma? Esa curiosidad es la que hace que se lea la segunda línea, y la tercera, y el capítulo entero."}, {"heading": "¿Qué largo debe tener el primer capítulo?", "text": "No hay una regla fija. Lo importante es que no se haga eterno antes de que pase algo interesante.\nPara leer en línea, muchas personas disfrutan capítulos que se leen en diez o quince minutos: lo suficiente para que pase algo, y lo justo para leerlos en un descanso. Si tu primer capítulo es mucho más largo, revisa si puedes empezar más tarde en la historia o dividirlo en dos."}, {"heading": "En resumen", "text": "Para empezar el primer capítulo, comienza donde algo se mueve, presenta a alguien interesante en una situación que despierte curiosidad, no lo expliques todo y termina con una pregunta que obligue a seguir leyendo."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-crear-tension-narrativa$consejo$,
    8,
    $consejo$¿Cómo crear tensión narrativa?$consejo$,
    $consejo$Cómo crear tensión narrativa para que tu historia atrape: obstáculos, secretos, decisiones difíciles y preguntas abiertas. Consejos de tía FriBuk.$consejo$,
    $consejo$La tensión aparece cuando queremos saber qué va a pasar. Pon obstáculos en el camino de tus personajes y no resuelvas todo inmediatamente. Una decisión difícil, un secreto o algo que podría salir mal pueden ser suficientes para mantener al lector pensando: «¿y ahora qué?».$consejo$,
    $consejo$explica$consejo$,
    $consejo$[{"heading": "", "text": "La tensión narrativa es ese momento en que el lector dice «un capítulo más»… y de pronto son las tres de la mañana. Eso queremos.\nNo hace falta escribir un thriller para tener tensión. Una historia de amor, una comedia o un fanfic tranquilo también la necesitan. Veamos cómo crearla."}, {"heading": "¿Qué es la tensión narrativa?", "text": "Es la sensación de que **algo importante está en juego y no sabemos cómo va a terminar**. Aparece cuando el lector quiere saber qué va a pasar y la historia no se lo dice todavía.\nSin tensión, el lector puede cerrar el libro en cualquier momento. Con tensión, no puede."}, {"heading": "Obstáculos, no paseos", "text": "Si a tu protagonista todo le sale bien a la primera, el lector se aburre. Ponle obstáculos en el camino y **no resuelvas todo de inmediato**.\nQue le cueste. Que dude. Que se equivoque. Que cuando por fin crea que lo logró, aparezca un problema nuevo. Ser un poco cruel con tus personajes es parte del oficio."}, {"heading": "Fuentes de tensión que no fallan", "text": "[•]**Una decisión difícil**, donde cualquier opción cuesta algo.\n[•]**Un secreto** que el lector conoce y el personaje no, o al revés.\n[•]**Algo que podría salir mal** en cualquier momento.\n[•]**Un reloj corriendo**: un plazo, una cuenta regresiva, una fecha que se acerca.\n[•]**Un conflicto entre personajes** que se quieren pero quieren cosas distintas.\nNo necesitas todas a la vez. Con una bien usada alcanza."}, {"heading": "¿Cómo mantener la tensión durante toda la historia?", "text": "El truco está en el ritmo: **responde una pregunta y abre otra**. Cada vez que resuelves algo, deja otra cosa pendiente. Así el lector siempre tiene un motivo para seguir.\nTambién ayuda alternar: después de una escena muy intensa, dale al lector un respiro. Una conversación tranquila, un momento de humor. La tensión constante agota; la tensión que sube y baja engancha."}, {"heading": "Errores que matan la tensión", "text": "[•]**Revelar todo demasiado pronto.** Si el lector ya sabe cómo termina, ¿para qué sigue?\n[•]**Resolver los problemas por casualidad.** Si un milagro salva al protagonista, el lector se siente engañado.\n[•]**Que no haya nada en juego.** Si fallar no tiene consecuencias, ganar tampoco importa."}, {"heading": "Un ejemplo práctico", "text": "Escena sin tensión: Ana va a la casa de su abuela, toma té y vuelve a su casa.\nLa misma escena con tensión: Ana va a la casa de su abuela con una noticia que no sabe cómo darle. Su abuela, mientras sirve el té, le comenta que su prima ya le contó «algo» por teléfono. Ana no sabe qué le contó.\nNo cambió el lugar ni los personajes. Cambió que ahora hay **algo en juego** (la noticia) y **algo que no sabemos** (qué le contaron a la abuela). El lector ya está inclinado hacia adelante, esperando.\nAsí de simple puede ser. No necesitas explosiones: necesitas una pregunta que importe."}, {"heading": "¿Y en una historia de romance o comedia?", "text": "También necesitan tensión, solo que de otro tipo. En un romance, la tensión es «¿se van a dar cuenta de lo que sienten?» o «¿qué los va a separar ahora?». En una comedia, es «¿cómo va a salir de este enredo?».\nEl principio es el mismo en cualquier género: algo que el personaje quiere, algo que se lo complica y un lector que no puede adivinar del todo cómo termina."}, {"heading": "En resumen", "text": "Para crear tensión narrativa, pon obstáculos reales, no resuelvas todo de inmediato, usa secretos, decisiones difíciles o plazos, y responde una pregunta abriendo otra. Que el lector siempre tenga un «¿y ahora qué?»."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$errores-comunes-al-comenzar-a-escribir$consejo$,
    9,
    $consejo$¿Cuáles son los errores comunes al comenzar a escribir?$consejo$,
    $consejo$Los errores más comunes al comenzar a escribir una historia y cómo evitarlos: perfeccionismo, explicar de más y abandonar ideas. Consejos de tía FriBuk.$consejo$,
    $consejo$Querer que el primer capítulo sea perfecto, explicar demasiado, introducir demasiados personajes de golpe o abandonar una idea porque «no quedó bien». Escribir también es corregir. Tu primer borrador no tiene que ser perfecto: tiene que existir. ¡El primer gran paso es intentarlo!$consejo$,
    $consejo$senala$consejo$,
    $consejo$[{"heading": "", "text": "Todos los cometimos. Algunos con más estilo que otros. Equivocarse al empezar a escribir no es un problema: es parte del camino. El problema es no darse cuenta.\nEstos son los errores más comunes al comenzar a escribir, y cómo salir de ellos."}, {"heading": "1. Querer que el primer capítulo sea perfecto", "text": "Lo reescribes, lo pules, lo vuelves a reescribir… y nunca pasas al capítulo dos. ¿En serio?\nEl primer capítulo lo vas a cambiar igual cuando termines la historia, porque para entonces sabrás mucho más de ella. **Avanza.** La perfección se busca al corregir, no al escribir."}, {"heading": "2. Explicarlo todo", "text": "Explicar lo que siente el personaje, por qué lo siente, qué significa, y por si acaso, explicarlo otra vez. El lector no necesita tanto.\n**Confía en el lector**: entiende más de lo que crees y disfruta descubrir cosas por su cuenta. Muestra, sugiere, y deja que complete."}, {"heading": "3. Presentar demasiados personajes de golpe", "text": "Diez nombres en la primera página: la protagonista, sus tres hermanos, sus dos mejores amigas, el profesor, el vecino y el gato. Nadie recuerda diez nombres en una página. Ni tú.\nPresenta a los personajes de a poco, cuando aparezcan en la historia, y dale a cada uno algo que lo distinga."}, {"heading": "4. Abandonar una idea porque «no quedó bien»", "text": "Escribes un párrafo, no te gusta, y decides que la historia entera no sirve. ¿En serio vas a renunciar a una historia por un párrafo feo?\nBórralo y sigue. Un mal párrafo no es una mala historia. Es un borrador, que es exactamente lo que tiene que ser."}, {"heading": "5. Compararse con autores consagrados", "text": "Lees tu primer capítulo al lado de tu libro favorito y quieres tirar el computador por la ventana. No lo hagas: estás comparando tu borrador con un libro que pasó por años de correcciones y editores.\nCompárate solo con lo que escribías hace un año. Ahí vas a ver tu progreso."}, {"heading": "Escribir también es corregir", "text": "Tu primer borrador no tiene que ser perfecto: **tiene que existir**. Corregir es parte del oficio, no un fracaso. Los libros que amas también tuvieron borradores horribles.\nEl primer gran paso es intentarlo. El segundo, terminar."}, {"heading": "6. Escribir sin leer", "text": "Quien quiere escribir y no lee es como quien quiere cocinar sin probar la comida. Leer te enseña ritmo, estructura, diálogos y vocabulario sin que te des cuenta.\nLee de todo: lo que te gusta, lo que nunca leerías y también lo que escriben otras personas que están empezando, como tú."}, {"heading": "7. No terminar nada", "text": "Cinco historias empezadas, ninguna terminada. Te suena, ¿verdad? Siempre aparece una idea nueva más brillante que la que tienes entre manos.\nAnota la idea nueva, guárdala y vuelve a la que estabas escribiendo. Terminar una historia, aunque sea corta e imperfecta, te enseña más que empezar diez."}, {"heading": "8. Escribir para darle en el gusto a todos", "text": "Si intentas que tu historia le guste a todo el mundo, vas a terminar con una historia que no emociona a nadie.\nEscribe la historia que a ti te gustaría leer. Siempre va a haber lectores que la busquen, justo porque nadie más la escribió como tú."}, {"heading": "En resumen", "text": "Los errores más comunes al empezar a escribir son buscar la perfección en el primer capítulo, explicar de más, presentar demasiados personajes, abandonar ideas por un mal párrafo y compararse con autores consagrados. Escribe primero, corrige después."}]$consejo$::jsonb,
    'draft'
);

insert into public.writing_tips
    (slug, position, title, description, summary, pose, sections, status)
values (
    $consejo$como-superar-el-bloqueo-creativo$consejo$,
    10,
    $consejo$¿Cómo superar el bloqueo creativo?$consejo$,
    $consejo$Cómo superar el bloqueo creativo o bloqueo de escritor: técnicas simples para destrabarte y volver a escribir tu historia. Consejos de tía FriBuk.$consejo$,
    $consejo$Cuando llevas horas mirando una página en blanco, insistir no siempre ayuda. Cambia de escena, escribe algo que no tenías planeado o deja la historia por un rato. También puedes escribir cualquier cosa durante diez minutos, sin preocuparte por si sirve. A veces el bloqueo se rompe simplemente dejando de exigirnos una buena idea. Tip de tía FriBuk: ¡juega algo, ve a tus amigos, lee otro libro, ve una peli! Distráete y, cuando menos lo esperes, se te vendrá la idea a la cabeza.$consejo$,
    $consejo$pensativa$consejo$,
    $consejo$[{"heading": "", "text": "Llevas horas mirando la página en blanco, y la página en blanco te mira de vuelta. Con cierta soberbia, además.\nEl bloqueo creativo, o bloqueo del escritor, le pasa a cualquiera que escriba: a quien empieza y a quien lleva veinte libros. No significa que no tengas talento. Significa que algo se trabó. Veamos cómo destrabarlo."}, {"heading": "¿Por qué aparece el bloqueo creativo?", "text": "Las causas más comunes son tres: **exigirse demasiado**, **no saber hacia dónde va la historia** y **el cansancio**. A veces es una mezcla de las tres.\nIdentificar cuál es tu caso ayuda mucho, porque cada una se resuelve distinto."}, {"heading": "Insistir no siempre ayuda", "text": "Si una escena no sale, no te quedes golpeando la misma puerta durante horas. Prueba otra cosa:\n[•]Escribe otra escena, una que sí tengas clara.\n[•]Escribe algo que no tenías planeado: una escena extra, un recuerdo de un personaje.\n[•]Deja la historia descansar un rato. Volver con ojos frescos hace milagros."}, {"heading": "La técnica de los diez minutos", "text": "Pon un temporizador y escribe cualquier cosa durante diez minutos, **sin parar y sin juzgar**. Sobre tu historia o sobre lo que comiste ayer. Nadie lo va a leer.\nA veces el bloqueo se rompe justo cuando dejas de exigirte una buena idea. Muchas veces, en el minuto ocho aparece algo que sirve."}, {"heading": "¿Y si no sé hacia dónde va mi historia?", "text": "Entonces el bloqueo no es de inspiración, es de rumbo. Vuelve a lo básico: ¿qué quiere tu protagonista? ¿Qué se lo impide? ¿Qué es lo peor que podría pasarle ahora?\nResponder esas preguntas suele mostrar el siguiente paso. Y si no, revisa el esquema de tu trama: quizás la historia te está pidiendo cambiar de camino."}, {"heading": "El tip de tía FriBuk: sal a vivir", "text": "Mi favorito: ¡juega algo, ve a tus amigos, lee otro libro, ve una peli! Distráete de verdad, sin culpa.\nLas ideas llegan cuando menos las esperas, casi siempre lejos del teclado: en la ducha, en el bus, a punto de dormir. Por eso, ten siempre a mano dónde anotarlas."}, {"heading": "¿Cómo prevenir el bloqueo creativo?", "text": "Mejor que salir del bloqueo es no caer tan seguido. Algunos hábitos que ayudan:\n[•]**Escribe un poco cada día** o en días fijos, aunque sean diez minutos. La costumbre le gana a la inspiración.\n[•]**Ponte metas pequeñas:** una escena, quinientas palabras. Las metas enormes paralizan.\n[•]**Termina la sesión sabiendo qué viene.** Deja anotado lo que pasa después: al día siguiente no empiezas en blanco.\n[•]**Ten una libreta de ideas:** frases, nombres, escenas sueltas. Cuando te bloquees, ábrela.\nY si necesitas ordenar tus días de escritura, en FriBuk puedes elegirlos al crear tu historia y te avisamos cuando te toca escribir."}, {"heading": "¿Y si el bloqueo dura semanas?", "text": "Pasa, y está bien. A veces la cabeza necesita un descanso más largo, sobre todo en épocas de mucho estrés o cansancio. Escribir no es una carrera.\nMientras tanto, mantén el vínculo con la escritura de forma liviana: lee, anota ideas sueltas, escribe algo corto que no tenga nada que ver con tu historia. Cuando vuelvas, la historia va a estar ahí, esperándote."}, {"heading": "En resumen", "text": "Para superar el bloqueo creativo, deja de exigirte, cambia de escena, escribe diez minutos sin juzgar, revisa hacia dónde va tu historia y, sobre todo, descansa y sal a vivir. Tienes potencial, no lo olvides. Descansa un rato… y después, a escribir."}]$consejo$::jsonb,
    'draft'
);
